import sys

def max_digit_sum(x):
    x_str = str(x)
    n = len(x_str)

    # Start with the highest possible number with the same length
    result = [9] * n

    # Check if we can use the full number
    if int(''.join(map(str, result))) <= x:
        return ''.join(map(str, result))

    # Otherwise, we need to adjust the digits
    for i in range(n):
        if x_str[i] != '0':
            # Set the current digit to one less than x_str[i]
            result[i] = int(x_str[i]) - 1
            # Set all following digits to 9
            result[i+1:] = [9] * (n - i - 1)
            # Check if this result is valid
            if int(''.join(map(str, result))) <= x:
                return ''.join(map(str, result))

    # If no valid result was found, return x itself
    return x_str

